// SubscriptionOrderByField represents a field that can be used for ordering
type SubscriptionOrderByField string

const (
	SubscriptionOrderById         SubscriptionOrderByField = "id"
	SubscriptionOrderBySubscriber SubscriptionOrderByField = "subscriber"
	SubscriptionOrderByDeletedAt  SubscriptionOrderByField = "deleted_at"
	SubscriptionOrderByDeletedBy  SubscriptionOrderByField = "deleted_by"
)

// SubscriptionOrderBy specifies ordering for Subscription queries
type SubscriptionOrderBy struct {
	Field SubscriptionOrderByField
	Desc  bool
}

// SubscriptionGetOptions contains options for Subscription GetOne operations
type SubscriptionGetOptions struct {
	// Fields specifies which fields to select (if zero, selects all fields)
	Fields SubscriptionFields
}

// SubscriptionFindOptions contains options for Subscription Find operations
type SubscriptionFindOptions struct {
	// Fields specifies which fields to select (if zero, selects all fields)
	Fields SubscriptionFields
	// OrderBy specifies sorting order
	OrderBy []SubscriptionOrderBy
	// Limit limits the number of results (default 100)
	Limit int
	// Offset skips the first N results (for pagination)
	Offset int
	// IncludeDeleted includes soft-deleted records in results (default false)
	IncludeDeleted bool
	// SkipCount reads the rows without counting them first: FindMany's
	// total is then -1 (D89).
	SkipCount bool
}

// SubscriptionSortField is a field FindPage orders Subscription rows by, by its
// schema name (D60, amended): its primary key, or a column of one value of
// text, a number or a time.
type SubscriptionSortField string

const (
	SubscriptionSortById         SubscriptionSortField = "id"
	SubscriptionSortBySubscriber SubscriptionSortField = "subscriber"
)

// SubscriptionSort is the order FindPage reads Subscription rows in: Field,
// ascending, or descending when Desc; ties break by id in the same
// direction. The zero value orders by id, ascending.
type SubscriptionSort struct {
	Field SubscriptionSortField
	Desc  bool
}

// ParseSubscriptionSort reads a sort as a page request writes it, "subscriber" or
// "-subscriber": an error for a field Subscription cannot be sorted by.
func ParseSubscriptionSort(text string) (SubscriptionSort, error) {
	parsed := SubscriptionSort{Field: SubscriptionSortField(strings.TrimPrefix(text, "-")), Desc: strings.HasPrefix(text, "-")}
	switch parsed.Field {
	case SubscriptionSortById, SubscriptionSortBySubscriber:
		return parsed, nil
	}
	return SubscriptionSort{}, fmt.Errorf("orm: Subscription sorts by id and subscriber, not %q", text)
}

// SubscriptionUniqueKey names a unique key of Subscription that UpsertOne and
// UpsertMany are keyed by (D79, D89): its primary key, a @unique field, or a
// unique @index, by its fields joined by ",".
type SubscriptionUniqueKey string

const (
	SubscriptionUniqueById              SubscriptionUniqueKey = "id"
	SubscriptionUniqueBySubscriberLabel SubscriptionUniqueKey = "subscriber,label"
)

// SubscriptionPageKey is the position of a Subscription row in a FindPage order: the
// row's id, as a cursor holds it, {"id": ...}. FindPage reads the row's
// value of its sort field from the table, so a key is the same in every order
// and its length is the id's, whatever the row holds (D60, amended).
type SubscriptionPageKey struct {
	Id types.IdentityUUID `json:"id"`
}

// arg is the key's id as the repository writes its column. A key without
// one is ErrPageKey.
func (k *SubscriptionPageKey) arg() (any, error) {
	var zeroKey types.IdentityUUID
	if k.Id == zeroKey {
		return nil, fmt.Errorf("%w: the Subscription key holds no id", ErrPageKey)
	}
	return k.Id.ToUUID(), nil
}

// subscriptionPageKeyOf is row's key: its id.
func subscriptionPageKeyOf(row *types.Subscription) *SubscriptionPageKey {
	key := &SubscriptionPageKey{}
	if row.Id != nil {
		key.Id = *row.Id
	}
	return key
}

// SubscriptionPageOptions are FindPage's options.
type SubscriptionPageOptions struct {
	// Fields specifies which fields to select, as FindMany's do; zero is an
	// error. A page reads the id too, which Next holds.
	Fields SubscriptionFields
	// Sort is the order the rows are read in.
	Sort SubscriptionSort
	// After is the key of the last row of the page before, nil for the first page.
	After *SubscriptionPageKey
	// Limit is the rows a page holds: 1 or more, 100 when 0.
	Limit int
	// IncludeDeleted includes soft-deleted records in results (default false)
	IncludeDeleted bool
}

// SubscriptionPage is a page of Subscription rows in FindPage's order: at most
// Limit rows, and Next, the key of the last of them, when more rows follow.
type SubscriptionPage struct {
	Rows []*types.Subscription
	Next *SubscriptionPageKey
}

