// conditions are the filter's conditions, each value appended to args, its
// placeholder numbered from paramOffset+1.
func (f *PurchaseFilter) conditions(args *[]interface{}, paramOffset int) []string {
	if f == nil {
		return nil
	}

	var conditions []string
	paramNum := paramOffset
	if f.Id != nil {
		if f.Id.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.id = $%d`, paramNum))
			*args = append(*args, f.Id.Eq.ToUUID())
		}
		if f.Id.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.id IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, f.Id.Ne.ToUUID())
		}
		if len(f.Id.In) > 0 {
			placeholders := make([]string, len(f.Id.In))
			for i, id := range f.Id.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`purchase.id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Id.NotIn) > 0 {
			placeholders := make([]string, len(f.Id.NotIn))
			for i, id := range f.Id.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`(purchase.id IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Id.IsNull != nil {
			if *f.Id.IsNull {
				conditions = append(conditions, `purchase.id IS NULL`)
			} else {
				conditions = append(conditions, `purchase.id IS NOT NULL`)
			}
		}
	}
	if f.Total != nil {
		if f.Total.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total = $%d`, paramNum))
			*args = append(*args, *f.Total.Eq)
		}
		if f.Total.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, *f.Total.Ne)
		}
		if f.Total.Gt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total > $%d`, paramNum))
			*args = append(*args, *f.Total.Gt)
		}
		if f.Total.Gte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total >= $%d`, paramNum))
			*args = append(*args, *f.Total.Gte)
		}
		if f.Total.Lt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total < $%d`, paramNum))
			*args = append(*args, *f.Total.Lt)
		}
		if f.Total.Lte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total <= $%d`, paramNum))
			*args = append(*args, *f.Total.Lte)
		}
		if f.Total.Between != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total >= $%d`, paramNum))
			*args = append(*args, f.Total.Between.Min)
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.total <= $%d`, paramNum))
			*args = append(*args, f.Total.Between.Max)
		}
		if len(f.Total.In) > 0 {
			placeholders := make([]string, len(f.Total.In))
			for i, value := range f.Total.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`purchase.total IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Total.NotIn) > 0 {
			placeholders := make([]string, len(f.Total.NotIn))
			for i, value := range f.Total.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`(purchase.total IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Total.IsNull != nil {
			if *f.Total.IsNull {
				conditions = append(conditions, `purchase.total IS NULL`)
			} else {
				conditions = append(conditions, `purchase.total IS NOT NULL`)
			}
		}
	}
	if f.CustomerID != nil {
		if f.CustomerID.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.customer_id = $%d`, paramNum))
			*args = append(*args, f.CustomerID.Eq.ToUUID())
		}
		if f.CustomerID.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`purchase.customer_id IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, f.CustomerID.Ne.ToUUID())
		}
		if len(f.CustomerID.In) > 0 {
			placeholders := make([]string, len(f.CustomerID.In))
			for i, id := range f.CustomerID.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`purchase.customer_id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.CustomerID.NotIn) > 0 {
			placeholders := make([]string, len(f.CustomerID.NotIn))
			for i, id := range f.CustomerID.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`(purchase.customer_id IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.CustomerID.IsNull != nil {
			if *f.CustomerID.IsNull {
				conditions = append(conditions, `purchase.customer_id IS NULL`)
			} else {
				conditions = append(conditions, `purchase.customer_id IS NOT NULL`)
			}
		}
	}
	if f.Customer != nil {
		before := len(*args)
		through := f.Customer.conditions(args, paramNum)
		paramNum += len(*args) - before
		where := ""
		if len(through) > 0 {
			where = " WHERE " + strings.Join(through, " AND ")
		}
		conditions = append(conditions, fmt.Sprintf(`purchase.customer_id IN (SELECT customer.id FROM customer%s)`, where))
	}

	// AllOf's filters' conditions are the filter's own, ANDed (D99), each
	// one's placeholders numbered after the last.
	for i := range f.AllOf {
		before := len(*args)
		conditions = append(conditions, f.AllOf[i].conditions(args, paramNum)...)
		paramNum += len(*args) - before
	}

	if len(f.AnyOf) > 0 {
		start := len(*args)
		branches := make([]string, 0, len(f.AnyOf))
		every := false
		for i := range f.AnyOf {
			before := len(*args)
			branch := f.AnyOf[i].conditions(args, paramNum)
			paramNum += len(*args) - before
			if len(branch) == 0 {
				every = true
				continue
			}
			branches = append(branches, "("+strings.Join(branch, " AND ")+")")
		}
		if every {
			// A branch of no condition keeps every row, and so does the
			// whole: the other branches' parameters go too. AnyOf is the
			// last condition, so no placeholder follows theirs.
			*args = (*args)[:start]
		} else {
			conditions = append(conditions, "("+strings.Join(branches, " OR ")+")")
		}
	}

	return conditions
}

// SubscriptionFilter provides filtering for Subscription queries
type SubscriptionFilter struct {
	Id         *UUIDFilter
	Subscriber *StringFilter
	// LabelID allows filtering by foreign key
	LabelID *UUIDFilter
	// Label keeps the rows whose label is among the live Label rows
	// the filter finds (D90): one condition, the foreign key in the keys of
	// those rows.
	Label *LabelFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []SubscriptionFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []SubscriptionFilter
}

